// ---- Appointments ---------------------------------------------------
function AppointmentsView({ db, update, onAdd, openDetail }) {
  const list = [...db.appointments].sort((a, b) => (a.date + a.time).localeCompare(b.date + b.time));
  function remove(id) { update(d => { d.appointments = d.appointments.filter(a => a.id !== id); return d; }); }
  const resultTone = { "Bekliyor": "warning", "Başarılı": "success", "Başarısız": "danger" };

  return (
    <div>
      <Header title="Randevular" subtitle={`${db.appointments.length} kayıt`} action={<GoldButton onClick={onAdd}><Plus size={15} /> Yeni Randevu</GoldButton>} />
      <Card className="overflow-hidden">
        <table className="w-full text-sm">
          <thead>
            <tr style={{ borderBottom: `1px solid ${C.line}` }}>
              {["Tarih", "Saat", "Danışan", "Hizmet Türü", "Sonuç", ""].map(h => (
                <th key={h} style={{ color: C.mutedFaint }} className="text-left font-medium text-xs uppercase tracking-wide px-4 py-3">{h}</th>
              ))}
            </tr>
          </thead>
          <tbody>
            {list.map(a => {
              const c = db.clients.find(c => c.id === a.clientId);
              return (
                <tr key={a.id} style={{ borderBottom: `1px solid ${C.line}` }}>
                  <td style={{ color: C.cream }} className="px-4 py-3">{fmtDate(a.date)}</td>
                  <td style={{ color: C.muted }} className="px-4 py-3">{a.time}</td>
                  <td style={{ color: C.cream }} className="px-4 py-3">{c ? c.name : "—"}</td>
                  <td style={{ color: C.muted }} className="px-4 py-3">{a.testType}</td>
                  <td className="px-4 py-3">
                    <button onClick={() => openDetail(a)}><Badge tone={resultTone[a.result]}>{a.result}</Badge></button>
                  </td>
                  <td className="px-4 py-3 text-right flex items-center justify-end gap-3">
                    <button onClick={() => openDetail(a)} style={{ color: C.gold }} className="text-xs font-medium">Detay</button>
                    <button onClick={() => remove(a.id)} style={{ color: C.mutedFaint }} className="hover:text-[#C1544A]"><Trash2 size={14} /></button>
                  </td>
                </tr>
              );
            })}
            {list.length === 0 && <tr><td colSpan={6} style={{ color: C.mutedFaint }} className="px-4 py-8 text-center text-xs">Henüz randevu yok.</td></tr>}
          </tbody>
        </table>
      </Card>
    </div>
  );
}

function ApptModal({ onClose, update, clients }) {
  const [f, setF] = useState({ clientId: clients[0]?.id || "", date: todayISO(), time: "10:00", testType: TEST_TYPES[0], result: "Bekliyor" });
  function submit(e) {
    e.preventDefault();
    if (!f.clientId) return;
    update(d => { d.appointments.push({ id: uid(), ...f, vision: "", hearing: "", coordination: "", reactionMs: "" }); return d; });
    onClose();
  }
  return (
    <Modal title="Yeni Randevu" onClose={onClose}>
      {clients.length === 0 ? <div style={{ color: C.muted }} className="text-sm">Önce bir danışan eklemelisiniz.</div> : (
        <form onSubmit={submit} className="flex flex-col gap-3">
          <Field label="Danışan">
            <SelectInput value={f.clientId} onChange={e => setF({ ...f, clientId: e.target.value })}>
              {clients.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}
            </SelectInput>
          </Field>
          <div className="grid grid-cols-2 gap-3">
            <Field label="Tarih"><TextInput type="date" value={f.date} onChange={e => setF({ ...f, date: e.target.value })} /></Field>
            <Field label="Saat"><TextInput type="time" value={f.time} onChange={e => setF({ ...f, time: e.target.value })} /></Field>
          </div>
          <Field label="Hizmet Türü">
            <SelectInput value={f.testType} onChange={e => setF({ ...f, testType: e.target.value })}>
              {TEST_TYPES.map(t => <option key={t}>{t}</option>)}
            </SelectInput>
          </Field>
          <div className="flex justify-end gap-2 mt-2">
            <GhostButton onClick={onClose}>Vazgeç</GhostButton>
            <GoldButton type="submit">Kaydet</GoldButton>
          </div>
        </form>
      )}
    </Modal>
  );
}

function ApptDetailModal({ onClose, update, appt, db, openReport }) {
  const c = db.clients.find(c => c.id === appt.clientId);
  const [f, setF] = useState({
    vision: appt.vision || "Geçti", hearing: appt.hearing || "Geçti",
    coordination: appt.coordination || "Geçti", reactionMs: appt.reactionMs || "",
    result: appt.result || "Bekliyor",
  });
  function save() {
    update(d => { d.appointments = d.appointments.map(a => a.id === appt.id ? { ...a, ...f } : a); return d; });
  }
  function saveAndClose() { save(); onClose(); }
  function saveAndReport() {
    save();
    onClose();
    openReport({ clientId: appt.clientId, testType: appt.testType, apptId: appt.id });
  }
  const resultColor = f.result === "Başarılı" ? C.success : f.result === "Başarısız" ? C.danger : C.warning;
  return (
    <Modal title="Test Detayı" onClose={onClose}>
      <div style={{ color: C.muted }} className="text-xs mb-3">{c?.name} · {appt.testType} · {fmtDate(appt.date)}</div>
      <div className="grid grid-cols-2 gap-3">
        <Field label="Görme"><SelectInput value={f.vision} onChange={e => setF({ ...f, vision: e.target.value })}>{PASS_FAIL.map(p => <option key={p}>{p}</option>)}</SelectInput></Field>
        <Field label="İşitme"><SelectInput value={f.hearing} onChange={e => setF({ ...f, hearing: e.target.value })}>{PASS_FAIL.map(p => <option key={p}>{p}</option>)}</SelectInput></Field>
        <Field label="Koordinasyon"><SelectInput value={f.coordination} onChange={e => setF({ ...f, coordination: e.target.value })}>{PASS_FAIL.map(p => <option key={p}>{p}</option>)}</SelectInput></Field>
        <Field label="Reaksiyon Süresi (ms)"><TextInput type="number" min="0" value={f.reactionMs} onChange={e => setF({ ...f, reactionMs: e.target.value })} /></Field>
      </div>
      <div className="mt-3">
        <Field label="Test Sonucu">
          <SelectInput value={f.result} onChange={e => setF({ ...f, result: e.target.value })} style={{ color: resultColor, fontWeight: 600, borderColor: resultColor }}>
            {APPT_RESULTS.map(r => <option key={r}>{r}</option>)}
          </SelectInput>
        </Field>
      </div>
      <div className="flex justify-between items-center gap-2 mt-5">
        {f.result === "Başarılı" ? (
          <GhostButton onClick={saveAndReport}><Sparkles size={14} /> Kaydet ve Rapor Oluştur</GhostButton>
        ) : <span />}
        <div className="flex gap-2">
          <GhostButton onClick={onClose}>Vazgeç</GhostButton>
          <GoldButton onClick={saveAndClose}>Kaydet</GoldButton>
        </div>
      </div>
    </Modal>
  );
}

// ---- Reports (rapor/belge takibi) ---------------------------------------
function nextReportNo(db) {
  const year = new Date().getFullYear();
  const n = db.reports.filter(r => r.reportNo?.includes(`-${year}-`)).length + 1;
  return `RP-${year}-${String(n).padStart(4, "0")}`;
}

function ReportsView({ db, update, onAdd }) {
  const list = [...db.reports].sort((a, b) => b.issueDate.localeCompare(a.issueDate));
  function remove(id) { update(d => { d.reports = d.reports.filter(r => r.id !== id); return d; }); }
  return (
    <div>
      <Header title="Raporlar" subtitle={`${db.reports.length} rapor/belge`} action={<GoldButton onClick={onAdd}><Plus size={15} /> Yeni Rapor</GoldButton>} />
      <Card className="overflow-hidden">
        <table className="w-full text-sm">
          <thead>
            <tr style={{ borderBottom: `1px solid ${C.line}` }}>
              {["Rapor No", "Danışan", "Hizmet Türü", "Kurum", "Veriliş", "Geçerlilik", "Durum", ""].map(h => (
                <th key={h} style={{ color: C.mutedFaint }} className="text-left font-medium text-xs uppercase tracking-wide px-4 py-3">{h}</th>
              ))}
            </tr>
          </thead>
          <tbody>
            {list.map(r => {
              const c = db.clients.find(c => c.id === r.clientId);
              const st = reportStatus(r.validUntil);
              return (
                <tr key={r.id} style={{ borderBottom: `1px solid ${C.line}` }}>
                  <td style={{ color: C.gold, fontFamily: SANS }} className="px-4 py-3 font-medium">{r.reportNo}</td>
                  <td style={{ color: C.cream }} className="px-4 py-3">{c ? c.name : "—"}</td>
                  <td style={{ color: C.muted }} className="px-4 py-3">{r.testType}</td>
                  <td style={{ color: C.muted }} className="px-4 py-3">{r.institution}</td>
                  <td style={{ color: C.muted }} className="px-4 py-3">{fmtDate(r.issueDate)}</td>
                  <td style={{ color: C.muted }} className="px-4 py-3">{fmtDate(r.validUntil)}</td>
                  <td className="px-4 py-3"><Badge tone={st.tone}>{st.label}</Badge></td>
                  <td className="px-4 py-3 text-right">
                    <button onClick={() => remove(r.id)} style={{ color: C.mutedFaint }} className="hover:text-[#C1544A]"><Trash2 size={14} /></button>
                  </td>
                </tr>
              );
            })}
            {list.length === 0 && <tr><td colSpan={8} style={{ color: C.mutedFaint }} className="px-4 py-8 text-center text-xs">Henüz rapor oluşturulmadı.</td></tr>}
          </tbody>
        </table>
      </Card>
    </div>
  );
}

function ReportModal({ onClose, update, clients, db, prefill }) {
  const initialClient = prefill?.clientId || clients[0]?.id || "";
  const initialType = prefill?.testType || TEST_TYPES[0];
  const [f, setF] = useState({
    clientId: initialClient, testType: initialType,
    institution: clients.find(c => c.id === initialClient)?.institution || INSTITUTIONS[0],
    issueDate: todayISO(), years: DEFAULT_VALIDITY_YEARS[initialType] || 5,
  });
  function submit(e) {
    e.preventDefault();
    if (!f.clientId) return;
    const reportNo = nextReportNo(db);
    const validUntil = addYears(f.issueDate, f.years);
    update(d => {
      d.reports.push({
        id: uid(), reportNo, clientId: f.clientId, testType: f.testType,
        institution: f.institution, issueDate: f.issueDate, validUntil,
        apptId: prefill?.apptId || null,
      });
      return d;
    });
    onClose();
  }
  return (
    <Modal title="Yeni Rapor / Belge" onClose={onClose} wide>
      {clients.length === 0 ? <div style={{ color: C.muted }} className="text-sm">Önce bir danışan eklemelisiniz.</div> : (
        <form onSubmit={submit} className="flex flex-col gap-3">
          <Field label="Danışan">
            <SelectInput value={f.clientId} onChange={e => setF({ ...f, clientId: e.target.value })}>
              {clients.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}
            </SelectInput>
          </Field>
          <div className="grid grid-cols-2 gap-3">
            <Field label="Hizmet Türü">
              <SelectInput value={f.testType} onChange={e => setF({ ...f, testType: e.target.value, years: DEFAULT_VALIDITY_YEARS[e.target.value] || 5 })}>
                {TEST_TYPES.map(t => <option key={t}>{t}</option>)}
              </SelectInput>
            </Field>
            <Field label="Talep Eden Kurum">
              <SelectInput value={f.institution} onChange={e => setF({ ...f, institution: e.target.value })}>
                {INSTITUTIONS.map(i => <option key={i}>{i}</option>)}
              </SelectInput>
            </Field>
          </div>
          <div className="grid grid-cols-2 gap-3">
            <Field label="Veriliş Tarihi"><TextInput type="date" value={f.issueDate} onChange={e => setF({ ...f, issueDate: e.target.value })} /></Field>
            <Field label="Geçerlilik (Yıl)"><TextInput type="number" min="1" max="10" value={f.years} onChange={e => setF({ ...f, years: e.target.value })} /></Field>
          </div>
          <div style={{ color: C.mutedFaint }} className="text-xs">Geçerlilik tarihi otomatik hesaplanacak: <span style={{ color: C.gold }}>{addYears(f.issueDate, f.years)}</span></div>
          <div className="flex justify-end gap-2 mt-2">
            <GhostButton onClick={onClose}>Vazgeç</GhostButton>
            <GoldButton type="submit">Rapor Oluştur</GoldButton>
          </div>
        </form>
      )}
    </Modal>
  );
}

